window.NEXO_LESSONS=[[{"title":"Gêneros textuais","summary":"Textos têm finalidades diferentes: a notícia informa fatos verificáveis; a reportagem aprofunda um tema; a fábula narra uma história que costuma trazer um ensinamento. Observe quem escreve, para quem e com qual objetivo.","example":"Uma notícia responde a perguntas como o quê, quando, onde e quem. Uma receita, por sua vez, orienta ações em etapas.","sections":[{"heading":"Conceitos essenciais","text":"Textos têm finalidades diferentes: a notícia informa fatos verificáveis; a reportagem aprofunda um tema; a fábula narra uma história que costuma trazer um ensinamento."},{"heading":"Como compreender e aplicar","text":"Observe quem escreve, para quem e com qual objetivo."}],"visual":{"icon":"📚","steps":["①","②","③"],"labels":["NOTÍCIA","FATO","INFORMAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Uma notícia responde a perguntas como o quê, quando, onde e quem. Uma receita, por sua vez, orienta ações em etapas."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “gêneros textuais” a um colega que faltou à aula. Comece pela ideia: Textos têm finalidades diferentes: a notícia informa fatos verificáveis; a reportagem aprofunda um tema; a fábula narra uma história que costuma trazer um ensinamento. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: NOTÍCIA → FATO → INFORMAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Gramática","summary":"A gramática ajuda a compreender como as palavras se organizam em frases. Substantivos nomeiam seres e ideias; adjetivos atribuem características; verbos indicam ações, estados ou fenômenos.","example":"Em 'As crianças curiosas pesquisam', 'crianças' é substantivo, 'curiosas' é adjetivo e 'pesquisam' é verbo.","sections":[{"heading":"Conceitos essenciais","text":"A gramática ajuda a compreender como as palavras se organizam em frases."},{"heading":"Como compreender e aplicar","text":"Substantivos nomeiam seres e ideias; adjetivos atribuem características; verbos indicam ações, estados ou fenômenos."}],"visual":{"icon":"📚","steps":["①","②","③"],"labels":["SUBSTANTIVO","ADJETIVO","VERBO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Em 'As crianças curiosas pesquisam', 'crianças' é substantivo, 'curiosas' é adjetivo e 'pesquisam' é verbo."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “gramática” a um colega que faltou à aula. Comece pela ideia: A gramática ajuda a compreender como as palavras se organizam em frases. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: SUBSTANTIVO → ADJETIVO → VERBO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Ortografia e pontuação","summary":"A ortografia orienta a escrita convencional das palavras. A pontuação organiza as ideias e ajuda a indicar perguntas, emoções, pausas e falas.","example":"'Você chegou?' é pergunta; 'Você chegou!' pode expressar surpresa. Na escrita, revise acentos e grafias que causam dúvidas.","sections":[{"heading":"Conceitos essenciais","text":"A ortografia orienta a escrita convencional das palavras."},{"heading":"Como compreender e aplicar","text":"A pontuação organiza as ideias e ajuda a indicar perguntas, emoções, pausas e falas."}],"visual":{"icon":"📚","steps":["①","②","③"],"labels":["PALAVRA","REVISÃO","PONTUAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"'Você chegou?' é pergunta; 'Você chegou!' pode expressar surpresa. Na escrita, revise acentos e grafias que causam dúvidas."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “ortografia e pontuação” a um colega que faltou à aula. Comece pela ideia: A ortografia orienta a escrita convencional das palavras. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PALAVRA → REVISÃO → PONTUAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Leitura e interpretação","summary":"Compreender um texto envolve localizar informações explícitas, identificar a ideia principal e inferir o que está sugerido por pistas. Uma inferência precisa ter apoio no texto.","example":"Se alguém pega um guarda-chuva ao ver nuvens escuras, podemos inferir que espera chuva, mas não afirmar que já choveu.","sections":[{"heading":"Conceitos essenciais","text":"Compreender um texto envolve localizar informações explícitas, identificar a ideia principal e inferir o que está sugerido por pistas."},{"heading":"Como compreender e aplicar","text":"Uma inferência precisa ter apoio no texto."}],"visual":{"icon":"📚","steps":["①","②","③"],"labels":["PISTAS","IDEIA CENTRAL","INFERÊNCIA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Se alguém pega um guarda-chuva ao ver nuvens escuras, podemos inferir que espera chuva, mas não afirmar que já choveu."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “leitura e interpretação” a um colega que faltou à aula. Comece pela ideia: Compreender um texto envolve localizar informações explícitas, identificar a ideia principal e inferir o que está sugerido por pistas. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PISTAS → IDEIA CENTRAL → INFERÊNCIA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Produção textual e coesão","summary":"Escrever bem envolve planejar o assunto, organizar parágrafos, escolher palavras adequadas ao leitor e revisar. Coesão é a ligação entre frases e ideias por conectivos e referências.","example":"'Estudei, portanto compreendi' indica consequência; 'estudei, porém tive dúvidas' indica oposição.","sections":[{"heading":"Conceitos essenciais","text":"Escrever bem envolve planejar o assunto, organizar parágrafos, escolher palavras adequadas ao leitor e revisar."},{"heading":"Como compreender e aplicar","text":"Coesão é a ligação entre frases e ideias por conectivos e referências."}],"visual":{"icon":"📚","steps":["①","②","③"],"labels":["PLANEJAR","CONECTAR","REVISAR"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"'Estudei, portanto compreendi' indica consequência; 'estudei, porém tive dúvidas' indica oposição."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “produção textual e coesão” a um colega que faltou à aula. Comece pela ideia: Escrever bem envolve planejar o assunto, organizar parágrafos, escolher palavras adequadas ao leitor e revisar. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PLANEJAR → CONECTAR → REVISAR. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Classes de palavras","summary":"As classes gramaticais cumprem funções diferentes. Substantivos nomeiam, artigos acompanham nomes, pronomes substituem ou acompanham nomes, adjetivos caracterizam e verbos expressam ações ou estados.","example":"Em 'Aquela menina canta bem', 'aquela' é pronome, 'menina' é substantivo, 'canta' é verbo e 'bem' é advérbio.","sections":[{"heading":"Conceitos essenciais","text":"As classes gramaticais cumprem funções diferentes."},{"heading":"Como compreender e aplicar","text":"Substantivos nomeiam, artigos acompanham nomes, pronomes substituem ou acompanham nomes, adjetivos caracterizam e verbos expressam ações ou estados."}],"visual":{"icon":"📚","steps":["①","②","③"],"labels":["NOMEAR","CARACTERIZAR","AGIR"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Em 'Aquela menina canta bem', 'aquela' é pronome, 'menina' é substantivo, 'canta' é verbo e 'bem' é advérbio."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “classes de palavras” a um colega que faltou à aula. Comece pela ideia: As classes gramaticais cumprem funções diferentes. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: NOMEAR → CARACTERIZAR → AGIR. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Frases, verbos e concordância","summary":"A frase comunica uma ideia; uma oração possui verbo. Em geral, o sujeito indica de quem se fala, e o predicado apresenta uma informação sobre ele. A concordância relaciona palavras em número e pessoa.","example":"Em 'Os alunos estudam', o verbo está no plural para concordar com 'os alunos'.","sections":[{"heading":"Conceitos essenciais","text":"A frase comunica uma ideia; uma oração possui verbo. Em geral, o sujeito indica de quem se fala, e o predicado apresenta uma informação sobre ele."},{"heading":"Como compreender e aplicar","text":"A concordância relaciona palavras em número e pessoa."}],"visual":{"icon":"📚","steps":["①","②","③"],"labels":["SUJEITO","VERBO","CONCORDÂNCIA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Em 'Os alunos estudam', o verbo está no plural para concordar com 'os alunos'."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “frases, verbos e concordância” a um colega que faltou à aula. Comece pela ideia: A frase comunica uma ideia; uma oração possui verbo. Em geral, o sujeito indica de quem se fala, e o predicado apresenta uma informação sobre ele. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: SUJEITO → VERBO → CONCORDÂNCIA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Literatura e linguagem","summary":"Textos literários podem criar sentidos figurados. A comparação aproxima elementos usando termos como 'como'; a metáfora estabelece uma aproximação sem esse termo; a personificação atribui características humanas a seres ou objetos.","example":"'Rápido como um raio' é comparação; 'o vento sussurrava' é personificação.","sections":[{"heading":"Conceitos essenciais","text":"Textos literários podem criar sentidos figurados."},{"heading":"Como compreender e aplicar","text":"A comparação aproxima elementos usando termos como 'como'; a metáfora estabelece uma aproximação sem esse termo; a personificação atribui características humanas a seres ou objetos."}],"visual":{"icon":"📚","steps":["①","②","③"],"labels":["LINGUAGEM","FIGURA","EFEITO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"'Rápido como um raio' é comparação; 'o vento sussurrava' é personificação."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “literatura e linguagem” a um colega que faltou à aula. Comece pela ideia: Textos literários podem criar sentidos figurados. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: LINGUAGEM → FIGURA → EFEITO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Leitura e inferências","summary":"Ler além do explícito é relacionar pistas, contexto e conhecimentos prévios. Uma boa inferência é plausível e pode ser justificada com trechos da leitura.","example":"Se a personagem treme e procura um casaco, pode estar com frio; sem outras pistas, não sabemos a temperatura exata.","sections":[{"heading":"Conceitos essenciais","text":"Ler além do explícito é relacionar pistas, contexto e conhecimentos prévios."},{"heading":"Como compreender e aplicar","text":"Uma boa inferência é plausível e pode ser justificada com trechos da leitura."}],"visual":{"icon":"📚","steps":["①","②","③"],"labels":["TEXTO","PISTAS","CONCLUSÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Se a personagem treme e procura um casaco, pode estar com frio; sem outras pistas, não sabemos a temperatura exata."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “leitura e inferências” a um colega que faltou à aula. Comece pela ideia: Ler além do explícito é relacionar pistas, contexto e conhecimentos prévios. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: TEXTO → PISTAS → CONCLUSÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Coesão, coerência e conectivos","summary":"Coesão conecta palavras e frases; coerência garante que as ideias façam sentido em conjunto. Conectivos podem indicar causa, consequência, oposição, adição e sequência.","example":"'Porque' costuma apresentar causa; 'porém' indica contraste; 'portanto' pode indicar conclusão.","sections":[{"heading":"Conceitos essenciais","text":"Coesão conecta palavras e frases; coerência garante que as ideias façam sentido em conjunto."},{"heading":"Como compreender e aplicar","text":"Conectivos podem indicar causa, consequência, oposição, adição e sequência."}],"visual":{"icon":"📚","steps":["①","②","③"],"labels":["IDEIAS","CONECTIVOS","SENTIDO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"'Porque' costuma apresentar causa; 'porém' indica contraste; 'portanto' pode indicar conclusão."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “coesão, coerência e conectivos” a um colega que faltou à aula. Comece pela ideia: Coesão conecta palavras e frases; coerência garante que as ideias façam sentido em conjunto. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: IDEIAS → CONECTIVOS → SENTIDO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Produção e revisão textual","summary":"A produção textual envolve planejamento, escrita, releitura e revisão. Revise clareza, organização, pontuação, concordância e adequação ao gênero e ao público.","example":"Antes de entregar uma carta de opinião, verifique se a tese está clara e se os argumentos realmente a sustentam.","sections":[{"heading":"Conceitos essenciais","text":"A produção textual envolve planejamento, escrita, releitura e revisão."},{"heading":"Como compreender e aplicar","text":"Revise clareza, organização, pontuação, concordância e adequação ao gênero e ao público."}],"visual":{"icon":"📚","steps":["①","②","③"],"labels":["RASCUNHO","REVISÃO","VERSÃO FINAL"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Antes de entregar uma carta de opinião, verifique se a tese está clara e se os argumentos realmente a sustentam."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “produção e revisão textual” a um colega que faltou à aula. Comece pela ideia: A produção textual envolve planejamento, escrita, releitura e revisão. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: RASCUNHO → REVISÃO → VERSÃO FINAL. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."}],[{"title":"Operações","summary":"Adição reúne quantidades; subtração calcula diferenças; multiplicação representa parcelas iguais; divisão distribui ou mede agrupamentos. Em problemas, identifique os dados e a pergunta antes de calcular.","example":"Se há 4 caixas com 6 lápis, são 4 × 6 = 24 lápis. Ao distribuir igualmente entre 3 crianças, cada uma recebe 8.","sections":[{"heading":"Conceitos essenciais","text":"Adição reúne quantidades; subtração calcula diferenças; multiplicação representa parcelas iguais; divisão distribui ou mede agrupamentos."},{"heading":"Como compreender e aplicar","text":"Em problemas, identifique os dados e a pergunta antes de calcular."}],"visual":{"icon":"🔢","steps":["①","②","③"],"labels":["DADOS","OPERAÇÃO","RESULTADO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Se há 4 caixas com 6 lápis, são 4 × 6 = 24 lápis. Ao distribuir igualmente entre 3 crianças, cada uma recebe 8."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “operações” a um colega que faltou à aula. Comece pela ideia: Adição reúne quantidades; subtração calcula diferenças; multiplicação representa parcelas iguais; divisão distribui ou mede agrupamentos. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: DADOS → OPERAÇÃO → RESULTADO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Frações e decimais","summary":"Frações representam partes de um todo dividido em partes iguais. O denominador indica em quantas partes o todo foi dividido; o numerador, quantas partes consideramos. Números decimais também representam partes da unidade.","example":"1/2 = 0,5 e 1/4 = 0,25. Para somar 1/2 + 1/4, reescreva 1/2 como 2/4: o resultado é 3/4.","sections":[{"heading":"Conceitos essenciais","text":"Frações representam partes de um todo dividido em partes iguais. O denominador indica em quantas partes o todo foi dividido; o numerador, quantas partes consideramos."},{"heading":"Como compreender e aplicar","text":"Números decimais também representam partes da unidade."}],"visual":{"icon":"🔢","steps":["①","②","③"],"labels":["TODO","PARTES","FRAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"1/2 = 0,5 e 1/4 = 0,25. Para somar 1/2 + 1/4, reescreva 1/2 como 2/4: o resultado é 3/4."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “frações e decimais” a um colega que faltou à aula. Comece pela ideia: Frações representam partes de um todo dividido em partes iguais. O denominador indica em quantas partes o todo foi dividido; o numerador, quantas partes consideramos. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: TODO → PARTES → FRAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Geometria e medidas","summary":"Figuras planas têm lados, vértices e ângulos. Perímetro é a medida do contorno; área é a medida da superfície. Atenção às unidades: comprimento em cm ou m; área em cm² ou m².","example":"Um retângulo de 6 m por 4 m tem área 24 m² e perímetro 20 m.","sections":[{"heading":"Conceitos essenciais","text":"Figuras planas têm lados, vértices e ângulos. Perímetro é a medida do contorno; área é a medida da superfície."},{"heading":"Como compreender e aplicar","text":"Atenção às unidades: comprimento em cm ou m; área em cm² ou m²."}],"visual":{"icon":"🔢","steps":["①","②","③"],"labels":["FIGURA","CONTORNO","SUPERFÍCIE"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Um retângulo de 6 m por 4 m tem área 24 m² e perímetro 20 m."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “geometria e medidas” a um colega que faltou à aula. Comece pela ideia: Figuras planas têm lados, vértices e ângulos. Perímetro é a medida do contorno; área é a medida da superfície. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: FIGURA → CONTORNO → SUPERFÍCIE. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Sistema de numeração","summary":"No sistema decimal, cada posição vale dez vezes a posição à direita. Unidades, dezenas, centenas e milhares ajudam a ler, compor e decompor números.","example":"Em 34.205, o algarismo 4 vale 4.000, e o algarismo 2 vale 200.","sections":[{"heading":"Conceitos essenciais","text":"No sistema decimal, cada posição vale dez vezes a posição à direita."},{"heading":"Como compreender e aplicar","text":"Unidades, dezenas, centenas e milhares ajudam a ler, compor e decompor números."}],"visual":{"icon":"🔢","steps":["①","②","③"],"labels":["ALGARISMO","POSIÇÃO","VALOR"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Em 34.205, o algarismo 4 vale 4.000, e o algarismo 2 vale 200."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “sistema de numeração” a um colega que faltou à aula. Comece pela ideia: No sistema decimal, cada posição vale dez vezes a posição à direita. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: ALGARISMO → POSIÇÃO → VALOR. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Múltiplos e divisores","summary":"Múltiplos surgem da multiplicação por números inteiros; divisores dividem um número sem deixar resto. O MMC ajuda em situações de coincidência de ciclos; o MDC, na formação de grupos iguais maiores.","example":"Os múltiplos de 6 incluem 6, 12, 18 e 24. Como 24 também é múltiplo de 8, MMC(6,8)=24.","sections":[{"heading":"Conceitos essenciais","text":"Múltiplos surgem da multiplicação por números inteiros; divisores dividem um número sem deixar resto."},{"heading":"Como compreender e aplicar","text":"O MMC ajuda em situações de coincidência de ciclos; o MDC, na formação de grupos iguais maiores."}],"visual":{"icon":"🔢","steps":["①","②","③"],"labels":["DIVISORES","MÚLTIPLOS","PADRÕES"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Os múltiplos de 6 incluem 6, 12, 18 e 24. Como 24 também é múltiplo de 8, MMC(6,8)=24."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “múltiplos e divisores” a um colega que faltou à aula. Comece pela ideia: Múltiplos surgem da multiplicação por números inteiros; divisores dividem um número sem deixar resto. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: DIVISORES → MÚLTIPLOS → PADRÕES. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Porcentagem","summary":"Porcentagem significa 'a cada cem'. Para calcular uma porcentagem, transforme-a em fração centesimal ou decimal e multiplique pelo valor total.","example":"15% de 200 = 0,15 × 200 = 30. Um desconto de R$ 30 em R$ 200 deixa o preço em R$ 170.","sections":[{"heading":"Conceitos essenciais","text":"Porcentagem significa 'a cada cem'."},{"heading":"Como compreender e aplicar","text":"Para calcular uma porcentagem, transforme-a em fração centesimal ou decimal e multiplique pelo valor total."}],"visual":{"icon":"🔢","steps":["①","②","③"],"labels":["VALOR TOTAL","PERCENTUAL","PARTE"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"15% de 200 = 0,15 × 200 = 30. Um desconto de R$ 30 em R$ 200 deixa o preço em R$ 170."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “porcentagem” a um colega que faltou à aula. Comece pela ideia: Porcentagem significa 'a cada cem'. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: VALOR TOTAL → PERCENTUAL → PARTE. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Álgebra e sequências","summary":"Sequências seguem padrões que podem ser descritos por regras. Letras podem representar valores desconhecidos; equações relacionam expressões iguais.","example":"Na sequência 3, 7, 11, 15, a regra é somar 4. Em x + 7 = 20, x = 13.","sections":[{"heading":"Conceitos essenciais","text":"Sequências seguem padrões que podem ser descritos por regras."},{"heading":"Como compreender e aplicar","text":"Letras podem representar valores desconhecidos; equações relacionam expressões iguais."}],"visual":{"icon":"🔢","steps":["①","②","③"],"labels":["PADRÃO","REGRA","TERMO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Na sequência 3, 7, 11, 15, a regra é somar 4. Em x + 7 = 20, x = 13."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “álgebra e sequências” a um colega que faltou à aula. Comece pela ideia: Sequências seguem padrões que podem ser descritos por regras. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PADRÃO → REGRA → TERMO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Estatística e probabilidade","summary":"A estatística organiza e interpreta dados por tabelas, gráficos e medidas como a média. A probabilidade compara casos favoráveis com todos os resultados igualmente possíveis.","example":"A média de 4, 6 e 8 é (4+6+8)/3=6. Em um dado justo, a chance de sair 2 é 1/6.","sections":[{"heading":"Conceitos essenciais","text":"A estatística organiza e interpreta dados por tabelas, gráficos e medidas como a média."},{"heading":"Como compreender e aplicar","text":"A probabilidade compara casos favoráveis com todos os resultados igualmente possíveis."}],"visual":{"icon":"🔢","steps":["①","②","③"],"labels":["DADOS","ORGANIZAÇÃO","INTERPRETAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"A média de 4, 6 e 8 é (4+6+8)/3=6. Em um dado justo, a chance de sair 2 é 1/6."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “estatística e probabilidade” a um colega que faltou à aula. Comece pela ideia: A estatística organiza e interpreta dados por tabelas, gráficos e medidas como a média. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: DADOS → ORGANIZAÇÃO → INTERPRETAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Expressões numéricas","summary":"Uma expressão reúne operações. Resolva primeiro parênteses; depois potências, multiplicações e divisões; por fim, adições e subtrações, respeitando a ordem da esquerda para a direita quando necessário.","example":"5 + 3 × 4 = 5 + 12 = 17, não 32.","sections":[{"heading":"Conceitos essenciais","text":"Uma expressão reúne operações."},{"heading":"Como compreender e aplicar","text":"Resolva primeiro parênteses; depois potências, multiplicações e divisões; por fim, adições e subtrações, respeitando a ordem da esquerda para a direita quando necessário."}],"visual":{"icon":"🔢","steps":["①","②","③"],"labels":["PARÊNTESES","MULT./DIV.","SOMA/SUB."],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"5 + 3 × 4 = 5 + 12 = 17, não 32."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “expressões numéricas” a um colega que faltou à aula. Comece pela ideia: Uma expressão reúne operações. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PARÊNTESES → MULT./DIV. → SOMA/SUB.. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Razões, porcentagens e descontos","summary":"Razão compara grandezas por divisão. Descontos e acréscimos percentuais são calculados em relação a um valor de referência. Sempre identifique qual é o valor inicial.","example":"20% de R$ 150 são R$ 30. Após o desconto, o produto custa R$ 120.","sections":[{"heading":"Conceitos essenciais","text":"Razão compara grandezas por divisão. Descontos e acréscimos percentuais são calculados em relação a um valor de referência."},{"heading":"Como compreender e aplicar","text":"Sempre identifique qual é o valor inicial."}],"visual":{"icon":"🔢","steps":["①","②","③"],"labels":["PREÇO","DESCONTO","VALOR FINAL"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"20% de R$ 150 são R$ 30. Após o desconto, o produto custa R$ 120."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “razões, porcentagens e descontos” a um colega que faltou à aula. Comece pela ideia: Razão compara grandezas por divisão. Descontos e acréscimos percentuais são calculados em relação a um valor de referência. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PREÇO → DESCONTO → VALOR FINAL. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Plano cartesiano","summary":"O plano cartesiano usa dois eixos perpendiculares. Um ponto é representado por (x,y): x é a posição horizontal, y é a vertical. Os sinais indicam a direção em relação à origem.","example":"O ponto (−2,3) fica duas unidades à esquerda e três acima da origem.","sections":[{"heading":"Conceitos essenciais","text":"O plano cartesiano usa dois eixos perpendiculares. Um ponto é representado por (x,y): x é a posição horizontal, y é a vertical."},{"heading":"Como compreender e aplicar","text":"Os sinais indicam a direção em relação à origem."}],"visual":{"icon":"🔢","steps":["①","②","③"],"labels":["EIXO X","EIXO Y","PONTO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"O ponto (−2,3) fica duas unidades à esquerda e três acima da origem."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “plano cartesiano” a um colega que faltou à aula. Comece pela ideia: O plano cartesiano usa dois eixos perpendiculares. Um ponto é representado por (x,y): x é a posição horizontal, y é a vertical. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: EIXO X → EIXO Y → PONTO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."}],[{"title":"Matéria e misturas","summary":"Matéria é tudo que possui massa e ocupa espaço. Misturas homogêneas apresentam aspecto uniforme; heterogêneas mostram mais de uma fase. A separação depende das propriedades dos componentes.","example":"Água e óleo formam mistura heterogênea; sal dissolvido em água forma mistura homogênea. Filtração separa sólidos insolúveis de líquidos.","sections":[{"heading":"Conceitos essenciais","text":"Matéria é tudo que possui massa e ocupa espaço. Misturas homogêneas apresentam aspecto uniforme; heterogêneas mostram mais de uma fase."},{"heading":"Como compreender e aplicar","text":"A separação depende das propriedades dos componentes."}],"visual":{"icon":"🔬","steps":["①","②","③"],"labels":["COMPONENTES","MISTURA","SEPARAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Água e óleo formam mistura heterogênea; sal dissolvido em água forma mistura homogênea. Filtração separa sólidos insolúveis de líquidos."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “matéria e misturas” a um colega que faltou à aula. Comece pela ideia: Matéria é tudo que possui massa e ocupa espaço. Misturas homogêneas apresentam aspecto uniforme; heterogêneas mostram mais de uma fase. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: COMPONENTES → MISTURA → SEPARAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Células e corpo humano","summary":"A célula é unidade básica dos seres vivos. Células formam tecidos; tecidos formam órgãos; órgãos integram sistemas que atuam juntos para manter o organismo.","example":"O sistema nervoso recebe e processa informações, enquanto o circulatório transporta substâncias pelo corpo.","sections":[{"heading":"Conceitos essenciais","text":"A célula é unidade básica dos seres vivos."},{"heading":"Como compreender e aplicar","text":"Células formam tecidos; tecidos formam órgãos; órgãos integram sistemas que atuam juntos para manter o organismo."}],"visual":{"icon":"🔬","steps":["①","②","③"],"labels":["CÉLULAS","TECIDOS","ÓRGÃOS"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"O sistema nervoso recebe e processa informações, enquanto o circulatório transporta substâncias pelo corpo."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “células e corpo humano” a um colega que faltou à aula. Comece pela ideia: A célula é unidade básica dos seres vivos. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: CÉLULAS → TECIDOS → ÓRGÃOS. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Terra e Universo","summary":"A Terra possui crosta, manto e núcleo. Rochas e fósseis ajudam a investigar a história do planeta. A Terra realiza rotação e translação, movimentos com efeitos observáveis.","example":"A rotação explica a alternância de dias e noites; fósseis registram vestígios ou restos de seres do passado.","sections":[{"heading":"Conceitos essenciais","text":"A Terra possui crosta, manto e núcleo. Rochas e fósseis ajudam a investigar a história do planeta."},{"heading":"Como compreender e aplicar","text":"A Terra realiza rotação e translação, movimentos com efeitos observáveis."}],"visual":{"icon":"🔬","steps":["①","②","③"],"labels":["CROSTA","MANTO","NÚCLEO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"A rotação explica a alternância de dias e noites; fósseis registram vestígios ou restos de seres do passado."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “terra e universo” a um colega que faltou à aula. Comece pela ideia: A Terra possui crosta, manto e núcleo. Rochas e fósseis ajudam a investigar a história do planeta. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: CROSTA → MANTO → NÚCLEO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Células e seres vivos","summary":"Seres vivos são formados por células. A membrana controla trocas com o ambiente; o citoplasma abriga estruturas celulares; o material genético contém informações hereditárias.","example":"Células vegetais têm parede celular e, em muitos tecidos, cloroplastos relacionados à fotossíntese.","sections":[{"heading":"Conceitos essenciais","text":"Seres vivos são formados por células."},{"heading":"Como compreender e aplicar","text":"A membrana controla trocas com o ambiente; o citoplasma abriga estruturas celulares; o material genético contém informações hereditárias."}],"visual":{"icon":"🔬","steps":["①","②","③"],"labels":["MEMBRANA","CITOPLASMA","NÚCLEO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Células vegetais têm parede celular e, em muitos tecidos, cloroplastos relacionados à fotossíntese."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “células e seres vivos” a um colega que faltou à aula. Comece pela ideia: Seres vivos são formados por células. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: MEMBRANA → CITOPLASMA → NÚCLEO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Sistema nervoso e sentidos","summary":"O sistema nervoso integra informações recebidas pelos órgãos dos sentidos e coordena respostas. Neurônios transmitem sinais; cérebro, medula e nervos atuam de forma articulada.","example":"Ao tocar algo quente, uma resposta reflexa pode retirar rapidamente a mão, ajudando na proteção.","sections":[{"heading":"Conceitos essenciais","text":"O sistema nervoso integra informações recebidas pelos órgãos dos sentidos e coordena respostas."},{"heading":"Como compreender e aplicar","text":"Neurônios transmitem sinais; cérebro, medula e nervos atuam de forma articulada."}],"visual":{"icon":"🔬","steps":["①","②","③"],"labels":["ESTÍMULO","SINAL NERVOSO","RESPOSTA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Ao tocar algo quente, uma resposta reflexa pode retirar rapidamente a mão, ajudando na proteção."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “sistema nervoso e sentidos” a um colega que faltou à aula. Comece pela ideia: O sistema nervoso integra informações recebidas pelos órgãos dos sentidos e coordena respostas. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: ESTÍMULO → SINAL NERVOSO → RESPOSTA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Sistema locomotor","summary":"O movimento depende da atuação conjunta de ossos, músculos e articulações. Ossos dão sustentação e proteção; músculos se contraem para movimentar partes do corpo.","example":"Ao dobrar o braço, músculos atuam de forma coordenada. Boa postura e atividades adequadas ajudam a preservar o sistema.","sections":[{"heading":"Conceitos essenciais","text":"O movimento depende da atuação conjunta de ossos, músculos e articulações."},{"heading":"Como compreender e aplicar","text":"Ossos dão sustentação e proteção; músculos se contraem para movimentar partes do corpo."}],"visual":{"icon":"🔬","steps":["①","②","③"],"labels":["OSSOS","ARTICULAÇÕES","MÚSCULOS"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Ao dobrar o braço, músculos atuam de forma coordenada. Boa postura e atividades adequadas ajudam a preservar o sistema."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “sistema locomotor” a um colega que faltou à aula. Comece pela ideia: O movimento depende da atuação conjunta de ossos, músculos e articulações. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: OSSOS → ARTICULAÇÕES → MÚSCULOS. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Terra, rochas e fósseis","summary":"Rochas podem ser ígneas, sedimentares ou metamórficas, conforme sua formação. Fósseis encontrados em camadas sedimentares ajudam a reconstruir ambientes antigos.","example":"Camadas inferiores não deformadas geralmente são mais antigas que as superiores, mas a análise geológica considera exceções.","sections":[{"heading":"Conceitos essenciais","text":"Rochas podem ser ígneas, sedimentares ou metamórficas, conforme sua formação."},{"heading":"Como compreender e aplicar","text":"Fósseis encontrados em camadas sedimentares ajudam a reconstruir ambientes antigos."}],"visual":{"icon":"🔬","steps":["①","②","③"],"labels":["ROCHA","CAMADAS","FÓSSEIS"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Camadas inferiores não deformadas geralmente são mais antigas que as superiores, mas a análise geológica considera exceções."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “terra, rochas e fósseis” a um colega que faltou à aula. Comece pela ideia: Rochas podem ser ígneas, sedimentares ou metamórficas, conforme sua formação. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: ROCHA → CAMADAS → FÓSSEIS. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Movimentos da Terra","summary":"A rotação é o giro da Terra em torno de seu eixo, durando aproximadamente 24 horas. A translação é o movimento ao redor do Sol; junto da inclinação do eixo, relaciona-se às estações.","example":"Quando um lado da Terra recebe luz solar, o outro pode estar à noite. As estações não dependem apenas da distância ao Sol.","sections":[{"heading":"Conceitos essenciais","text":"A rotação é o giro da Terra em torno de seu eixo, durando aproximadamente 24 horas."},{"heading":"Como compreender e aplicar","text":"A translação é o movimento ao redor do Sol; junto da inclinação do eixo, relaciona-se às estações."}],"visual":{"icon":"🔬","steps":["①","②","③"],"labels":["ROTAÇÃO","DIA/NOITE","TRANSLAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Quando um lado da Terra recebe luz solar, o outro pode estar à noite. As estações não dependem apenas da distância ao Sol."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “movimentos da terra” a um colega que faltou à aula. Comece pela ideia: A rotação é o giro da Terra em torno de seu eixo, durando aproximadamente 24 horas. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: ROTAÇÃO → DIA/NOITE → TRANSLAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Sistemas do corpo e saúde","summary":"Sistemas respiratório, digestório, circulatório, nervoso e locomotor atuam de forma integrada. Sono, alimentação, higiene e movimento contribuem para a saúde.","example":"Durante exercício, o corpo necessita de mais oxigênio e nutrientes, e a respiração e a frequência cardíaca podem aumentar.","sections":[{"heading":"Conceitos essenciais","text":"Sistemas respiratório, digestório, circulatório, nervoso e locomotor atuam de forma integrada."},{"heading":"Como compreender e aplicar","text":"Sono, alimentação, higiene e movimento contribuem para a saúde."}],"visual":{"icon":"🔬","steps":["①","②","③"],"labels":["RESPIRAÇÃO","CIRCULAÇÃO","MOVIMENTO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Durante exercício, o corpo necessita de mais oxigênio e nutrientes, e a respiração e a frequência cardíaca podem aumentar."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “sistemas do corpo e saúde” a um colega que faltou à aula. Comece pela ideia: Sistemas respiratório, digestório, circulatório, nervoso e locomotor atuam de forma integrada. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: RESPIRAÇÃO → CIRCULAÇÃO → MOVIMENTO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Ecossistemas e relações ambientais","summary":"Ecossistema reúne seres vivos e componentes não vivos em interação. Produtores captam energia, consumidores obtêm alimento de outros organismos e decompositores reciclam matéria.","example":"Em uma cadeia alimentar, capim → gafanhoto → sapo, o capim é produtor. A redução de uma população pode afetar outras.","sections":[{"heading":"Conceitos essenciais","text":"Ecossistema reúne seres vivos e componentes não vivos em interação."},{"heading":"Como compreender e aplicar","text":"Produtores captam energia, consumidores obtêm alimento de outros organismos e decompositores reciclam matéria."}],"visual":{"icon":"🔬","steps":["①","②","③"],"labels":["PRODUTORES","CONSUMIDORES","DECOMPOSITORES"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Em uma cadeia alimentar, capim → gafanhoto → sapo, o capim é produtor. A redução de uma população pode afetar outras."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “ecossistemas e relações ambientais” a um colega que faltou à aula. Comece pela ideia: Ecossistema reúne seres vivos e componentes não vivos em interação. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PRODUTORES → CONSUMIDORES → DECOMPOSITORES. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."}],[{"title":"Fontes e tempo histórico","summary":"Historiadores investigam mudanças e permanências usando fontes escritas, orais, visuais e materiais. Uma fonte precisa ser analisada considerando autoria, época, finalidade e contexto.","example":"Uma fotografia antiga mostra aspectos do passado, mas não explica sozinha todos os acontecimentos retratados.","sections":[{"heading":"Conceitos essenciais","text":"Historiadores investigam mudanças e permanências usando fontes escritas, orais, visuais e materiais."},{"heading":"Como compreender e aplicar","text":"Uma fonte precisa ser analisada considerando autoria, época, finalidade e contexto."}],"visual":{"icon":"🏛️","steps":["①","②","③"],"labels":["FONTE","CONTEXTO","INTERPRETAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Uma fotografia antiga mostra aspectos do passado, mas não explica sozinha todos os acontecimentos retratados."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “fontes e tempo histórico” a um colega que faltou à aula. Comece pela ideia: Historiadores investigam mudanças e permanências usando fontes escritas, orais, visuais e materiais. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: FONTE → CONTEXTO → INTERPRETAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Primeiras sociedades","summary":"Grupos humanos viveram de diferentes maneiras ao longo do tempo. O nomadismo envolve deslocamentos frequentes; em várias regiões, agricultura e criação de animais favoreceram assentamentos permanentes.","example":"O cultivo de alimentos e seu armazenamento ajudaram na formação de aldeias, sem que todos os povos adotassem o mesmo modo de vida.","sections":[{"heading":"Conceitos essenciais","text":"Grupos humanos viveram de diferentes maneiras ao longo do tempo."},{"heading":"Como compreender e aplicar","text":"O nomadismo envolve deslocamentos frequentes; em várias regiões, agricultura e criação de animais favoreceram assentamentos permanentes."}],"visual":{"icon":"🏛️","steps":["①","②","③"],"labels":["DESLOCAMENTO","CULTIVO","ALDEIAS"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"O cultivo de alimentos e seu armazenamento ajudaram na formação de aldeias, sem que todos os povos adotassem o mesmo modo de vida."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “primeiras sociedades” a um colega que faltou à aula. Comece pela ideia: Grupos humanos viveram de diferentes maneiras ao longo do tempo. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: DESLOCAMENTO → CULTIVO → ALDEIAS. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Civilizações antigas","summary":"Civilizações antigas desenvolveram formas diversas de governo, religião, escrita e trabalho. Rios favoreceram agricultura e circulação, mas cada sociedade tinha características próprias.","example":"O Nilo foi importante no Egito Antigo; Tigre e Eufrates, na Mesopotâmia.","sections":[{"heading":"Conceitos essenciais","text":"Civilizações antigas desenvolveram formas diversas de governo, religião, escrita e trabalho."},{"heading":"Como compreender e aplicar","text":"Rios favoreceram agricultura e circulação, mas cada sociedade tinha características próprias."}],"visual":{"icon":"🏛️","steps":["①","②","③"],"labels":["RIOS","AGRICULTURA","CIDADES"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"O Nilo foi importante no Egito Antigo; Tigre e Eufrates, na Mesopotâmia."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “civilizações antigas” a um colega que faltou à aula. Comece pela ideia: Civilizações antigas desenvolveram formas diversas de governo, religião, escrita e trabalho. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: RIOS → AGRICULTURA → CIDADES. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Fontes e tempo histórico","summary":"A história não é uma lista de datas: envolve processos, diferentes durações e perspectivas. Fontes históricas podem apresentar versões distintas de um mesmo fato.","example":"Cartas, relatos orais e objetos antigos devem ser comparados e situados no tempo.","sections":[{"heading":"Conceitos essenciais","text":"A história não é uma lista de datas: envolve processos, diferentes durações e perspectivas."},{"heading":"Como compreender e aplicar","text":"Fontes históricas podem apresentar versões distintas de um mesmo fato."}],"visual":{"icon":"🏛️","steps":["①","②","③"],"labels":["VESTÍGIO","AUTORIA","ÉPOCA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Cartas, relatos orais e objetos antigos devem ser comparados e situados no tempo."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “fontes e tempo histórico” a um colega que faltou à aula. Comece pela ideia: A história não é uma lista de datas: envolve processos, diferentes durações e perspectivas. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: VESTÍGIO → AUTORIA → ÉPOCA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Primeiros humanos","summary":"A história dos primeiros humanos é estudada com fósseis, ferramentas e outros vestígios. A fabricação de instrumentos, as migrações e a domesticação de plantas ocorreram em contextos diversos.","example":"Pinturas rupestres e utensílios ajudam a compreender atividades e formas de expressão de grupos antigos.","sections":[{"heading":"Conceitos essenciais","text":"A história dos primeiros humanos é estudada com fósseis, ferramentas e outros vestígios."},{"heading":"Como compreender e aplicar","text":"A fabricação de instrumentos, as migrações e a domesticação de plantas ocorreram em contextos diversos."}],"visual":{"icon":"🏛️","steps":["①","②","③"],"labels":["FÓSSEIS","FERRAMENTAS","HISTÓRIA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Pinturas rupestres e utensílios ajudam a compreender atividades e formas de expressão de grupos antigos."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “primeiros humanos” a um colega que faltou à aula. Comece pela ideia: A história dos primeiros humanos é estudada com fósseis, ferramentas e outros vestígios. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: FÓSSEIS → FERRAMENTAS → HISTÓRIA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Mesopotâmia e Egito","summary":"Mesopotâmia e Egito desenvolveram sociedades complexas ligadas ao uso da água e à agricultura. Governos, crenças, trabalhos e formas de escrita variaram entre elas.","example":"Os mesopotâmicos desenvolveram escrita cuneiforme; no Egito Antigo, usaram-se hieróglifos em determinados contextos.","sections":[{"heading":"Conceitos essenciais","text":"Mesopotâmia e Egito desenvolveram sociedades complexas ligadas ao uso da água e à agricultura."},{"heading":"Como compreender e aplicar","text":"Governos, crenças, trabalhos e formas de escrita variaram entre elas."}],"visual":{"icon":"🏛️","steps":["①","②","③"],"labels":["TIGRE/EUFRATES","NILO","SOCIEDADES"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Os mesopotâmicos desenvolveram escrita cuneiforme; no Egito Antigo, usaram-se hieróglifos em determinados contextos."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “mesopotâmia e egito” a um colega que faltou à aula. Comece pela ideia: Mesopotâmia e Egito desenvolveram sociedades complexas ligadas ao uso da água e à agricultura. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: TIGRE/EUFRATES → NILO → SOCIEDADES. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Grécia e Roma","summary":"As sociedades grega e romana influenciaram instituições, artes e leis, mas seus direitos eram restritos a grupos específicos. A democracia ateniense antiga não incluía todos os habitantes.","example":"Atenas ficou associada à democracia de cidadãos; Roma passou por monarquia, república e império.","sections":[{"heading":"Conceitos essenciais","text":"As sociedades grega e romana influenciaram instituições, artes e leis, mas seus direitos eram restritos a grupos específicos."},{"heading":"Como compreender e aplicar","text":"A democracia ateniense antiga não incluía todos os habitantes."}],"visual":{"icon":"🏛️","steps":["①","②","③"],"labels":["ATENAS","ROMA","CIDADANIA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Atenas ficou associada à democracia de cidadãos; Roma passou por monarquia, república e império."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “grécia e roma” a um colega que faltou à aula. Comece pela ideia: As sociedades grega e romana influenciaram instituições, artes e leis, mas seus direitos eram restritos a grupos específicos. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: ATENAS → ROMA → CIDADANIA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Povos indígenas e Américas","summary":"As Américas abrigavam sociedades muito diversas antes da colonização europeia. Povos desenvolveram técnicas agrícolas, cidades, redes de troca, conhecimentos e tradições.","example":"Maias, astecas e incas possuíam organizações distintas. Não devemos tratar todos os povos indígenas como um único grupo.","sections":[{"heading":"Conceitos essenciais","text":"As Américas abrigavam sociedades muito diversas antes da colonização europeia."},{"heading":"Como compreender e aplicar","text":"Povos desenvolveram técnicas agrícolas, cidades, redes de troca, conhecimentos e tradições."}],"visual":{"icon":"🏛️","steps":["①","②","③"],"labels":["MAIAS","ASTECAS","INCAS"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Maias, astecas e incas possuíam organizações distintas. Não devemos tratar todos os povos indígenas como um único grupo."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “povos indígenas e américas” a um colega que faltou à aula. Comece pela ideia: As Américas abrigavam sociedades muito diversas antes da colonização europeia. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: MAIAS → ASTECAS → INCAS. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Fontes históricas e tempo","summary":"Fontes históricas são vestígios interpretados para investigar o passado. Cronologias ajudam a ordenar eventos, mas processos podem ocorrer simultaneamente e em ritmos diferentes.","example":"Um diário expressa o ponto de vista de seu autor; compará-lo a outras fontes torna a interpretação mais cuidadosa.","sections":[{"heading":"Conceitos essenciais","text":"Fontes históricas são vestígios interpretados para investigar o passado."},{"heading":"Como compreender e aplicar","text":"Cronologias ajudam a ordenar eventos, mas processos podem ocorrer simultaneamente e em ritmos diferentes."}],"visual":{"icon":"🏛️","steps":["①","②","③"],"labels":["PASSADO","FONTES","CRONOLOGIA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Um diário expressa o ponto de vista de seu autor; compará-lo a outras fontes torna a interpretação mais cuidadosa."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “fontes históricas e tempo” a um colega que faltou à aula. Comece pela ideia: Fontes históricas são vestígios interpretados para investigar o passado. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PASSADO → FONTES → CRONOLOGIA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Civilizações americanas antigas","summary":"Maias, astecas e incas construíram sociedades com conhecimentos e formas de organização próprios. O ambiente influenciou práticas agrícolas e a ocupação dos territórios.","example":"Machu Picchu está associado aos incas; Tenochtitlán foi capital do império asteca.","sections":[{"heading":"Conceitos essenciais","text":"Maias, astecas e incas construíram sociedades com conhecimentos e formas de organização próprios."},{"heading":"Como compreender e aplicar","text":"O ambiente influenciou práticas agrícolas e a ocupação dos territórios."}],"visual":{"icon":"🏛️","steps":["①","②","③"],"labels":["MAIAS","ASTECAS","INCAS"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Machu Picchu está associado aos incas; Tenochtitlán foi capital do império asteca."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “civilizações americanas antigas” a um colega que faltou à aula. Comece pela ideia: Maias, astecas e incas construíram sociedades com conhecimentos e formas de organização próprios. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: MAIAS → ASTECAS → INCAS. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."}],[{"title":"Paisagens e espaço","summary":"Paisagem é o conjunto de elementos que podemos perceber em um lugar, incluindo componentes naturais e modificados pela sociedade. O espaço geográfico é produzido pelas relações entre natureza e ações humanas.","example":"Rios e montanhas são elementos naturais; ruas e edifícios são construções humanas.","sections":[{"heading":"Conceitos essenciais","text":"Paisagem é o conjunto de elementos que podemos perceber em um lugar, incluindo componentes naturais e modificados pela sociedade."},{"heading":"Como compreender e aplicar","text":"O espaço geográfico é produzido pelas relações entre natureza e ações humanas."}],"visual":{"icon":"🌎","steps":["①","②","③"],"labels":["NATUREZA","SOCIEDADE","PAISAGEM"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Rios e montanhas são elementos naturais; ruas e edifícios são construções humanas."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “paisagens e espaço” a um colega que faltou à aula. Comece pela ideia: Paisagem é o conjunto de elementos que podemos perceber em um lugar, incluindo componentes naturais e modificados pela sociedade. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: NATUREZA → SOCIEDADE → PAISAGEM. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Cartografia","summary":"Mapas representam espaços por símbolos, legendas, escalas e orientação. A rosa dos ventos indica direções; a escala relaciona distância no mapa e no terreno.","example":"Na escala 1:100.000, 1 cm no mapa representa 1 km na realidade.","sections":[{"heading":"Conceitos essenciais","text":"Mapas representam espaços por símbolos, legendas, escalas e orientação."},{"heading":"Como compreender e aplicar","text":"A rosa dos ventos indica direções; a escala relaciona distância no mapa e no terreno."}],"visual":{"icon":"🌎","steps":["①","②","③"],"labels":["LEGENDA","ORIENTAÇÃO","ESCALA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Na escala 1:100.000, 1 cm no mapa representa 1 km na realidade."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “cartografia” a um colega que faltou à aula. Comece pela ideia: Mapas representam espaços por símbolos, legendas, escalas e orientação. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: LEGENDA → ORIENTAÇÃO → ESCALA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Natureza e ambiente","summary":"O ambiente reúne ar, água, solo, seres vivos e suas interações. No ciclo da água, ocorrem evaporação, condensação, precipitação e infiltração.","example":"O vapor de água pode condensar formando gotículas que participam da formação de nuvens.","sections":[{"heading":"Conceitos essenciais","text":"O ambiente reúne ar, água, solo, seres vivos e suas interações."},{"heading":"Como compreender e aplicar","text":"No ciclo da água, ocorrem evaporação, condensação, precipitação e infiltração."}],"visual":{"icon":"🌎","steps":["①","②","③"],"labels":["EVAPORAÇÃO","CONDENSAÇÃO","CHUVA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"O vapor de água pode condensar formando gotículas que participam da formação de nuvens."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “natureza e ambiente” a um colega que faltou à aula. Comece pela ideia: O ambiente reúne ar, água, solo, seres vivos e suas interações. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: EVAPORAÇÃO → CONDENSAÇÃO → CHUVA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Paisagem e espaço geográfico","summary":"As paisagens mudam com processos naturais e ações humanas. Fotografias, mapas e relatos permitem comparar transformações ao longo do tempo.","example":"A construção de uma estrada pode alterar o uso do solo, a circulação de pessoas e a vegetação.","sections":[{"heading":"Conceitos essenciais","text":"As paisagens mudam com processos naturais e ações humanas."},{"heading":"Como compreender e aplicar","text":"Fotografias, mapas e relatos permitem comparar transformações ao longo do tempo."}],"visual":{"icon":"🌎","steps":["①","②","③"],"labels":["ANTES","TRANSFORMAÇÃO","DEPOIS"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"A construção de uma estrada pode alterar o uso do solo, a circulação de pessoas e a vegetação."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “paisagem e espaço geográfico” a um colega que faltou à aula. Comece pela ideia: As paisagens mudam com processos naturais e ações humanas. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: ANTES → TRANSFORMAÇÃO → DEPOIS. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Cartografia e localização","summary":"Localização usa referências como pontos cardeais, coordenadas e mapas. Latitude é medida a partir do Equador; longitude, a partir de Greenwich.","example":"Um ponto a 20° S e 45° O está nos hemisférios Sul e Ocidental.","sections":[{"heading":"Conceitos essenciais","text":"Localização usa referências como pontos cardeais, coordenadas e mapas."},{"heading":"Como compreender e aplicar","text":"Latitude é medida a partir do Equador; longitude, a partir de Greenwich."}],"visual":{"icon":"🌎","steps":["①","②","③"],"labels":["LATITUDE","LONGITUDE","LOCALIZAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Um ponto a 20° S e 45° O está nos hemisférios Sul e Ocidental."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “cartografia e localização” a um colega que faltou à aula. Comece pela ideia: Localização usa referências como pontos cardeais, coordenadas e mapas. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: LATITUDE → LONGITUDE → LOCALIZAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Clima e atmosfera","summary":"Tempo atmosférico descreve condições de curto prazo; clima é o comportamento habitual dessas condições em períodos longos. Temperatura, chuva, ventos e umidade variam entre regiões.","example":"Um dia frio não prova mudança no clima de uma região; é preciso observar dados de muitos anos.","sections":[{"heading":"Conceitos essenciais","text":"Tempo atmosférico descreve condições de curto prazo; clima é o comportamento habitual dessas condições em períodos longos."},{"heading":"Como compreender e aplicar","text":"Temperatura, chuva, ventos e umidade variam entre regiões."}],"visual":{"icon":"🌎","steps":["①","②","③"],"labels":["TEMPO","DADOS LONGOS","CLIMA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Um dia frio não prova mudança no clima de uma região; é preciso observar dados de muitos anos."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “clima e atmosfera” a um colega que faltou à aula. Comece pela ideia: Tempo atmosférico descreve condições de curto prazo; clima é o comportamento habitual dessas condições em períodos longos. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: TEMPO → DADOS LONGOS → CLIMA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Relevo, solo e água","summary":"Relevo reúne formas da superfície terrestre, como planaltos, planícies e depressões. Água, vento e gravidade participam da erosão; vegetação ajuda a proteger o solo.","example":"Em encostas desmatadas, chuvas intensas podem favorecer erosão e deslizamentos.","sections":[{"heading":"Conceitos essenciais","text":"Relevo reúne formas da superfície terrestre, como planaltos, planícies e depressões."},{"heading":"Como compreender e aplicar","text":"Água, vento e gravidade participam da erosão; vegetação ajuda a proteger o solo."}],"visual":{"icon":"🌎","steps":["①","②","③"],"labels":["RELEVO","ÁGUA","EROSÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Em encostas desmatadas, chuvas intensas podem favorecer erosão e deslizamentos."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “relevo, solo e água” a um colega que faltou à aula. Comece pela ideia: Relevo reúne formas da superfície terrestre, como planaltos, planícies e depressões. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: RELEVO → ÁGUA → EROSÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Sustentabilidade e recursos","summary":"Recursos naturais são utilizados pelas sociedades, mas podem ser esgotados ou degradados. Sustentabilidade envolve reduzir desperdícios, reutilizar materiais e cuidar dos ecossistemas.","example":"Economizar água e diminuir resíduos são atitudes que reduzem impactos ambientais.","sections":[{"heading":"Conceitos essenciais","text":"Recursos naturais são utilizados pelas sociedades, mas podem ser esgotados ou degradados."},{"heading":"Como compreender e aplicar","text":"Sustentabilidade envolve reduzir desperdícios, reutilizar materiais e cuidar dos ecossistemas."}],"visual":{"icon":"🌎","steps":["①","②","③"],"labels":["REDUZIR","REUTILIZAR","RECICLAR"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Economizar água e diminuir resíduos são atitudes que reduzem impactos ambientais."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “sustentabilidade e recursos” a um colega que faltou à aula. Comece pela ideia: Recursos naturais são utilizados pelas sociedades, mas podem ser esgotados ou degradados. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: REDUZIR → REUTILIZAR → RECICLAR. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Coordenadas e cartografia","summary":"Coordenadas geográficas permitem localizar pontos por latitude e longitude. Mapas temáticos destacam fenômenos específicos, como população, vegetação ou chuvas.","example":"Latitude 0° corresponde ao Equador; longitude 0° corresponde ao meridiano de Greenwich.","sections":[{"heading":"Conceitos essenciais","text":"Coordenadas geográficas permitem localizar pontos por latitude e longitude."},{"heading":"Como compreender e aplicar","text":"Mapas temáticos destacam fenômenos específicos, como população, vegetação ou chuvas."}],"visual":{"icon":"🌎","steps":["①","②","③"],"labels":["EQUADOR","GREENWICH","COORDENADAS"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Latitude 0° corresponde ao Equador; longitude 0° corresponde ao meridiano de Greenwich."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “coordenadas e cartografia” a um colega que faltou à aula. Comece pela ideia: Coordenadas geográficas permitem localizar pontos por latitude e longitude. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: EQUADOR → GREENWICH → COORDENADAS. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"População e espaço geográfico","summary":"A população ocupa e transforma espaços. Migração é deslocamento de pessoas entre lugares; urbanização envolve o crescimento e a concentração de atividades urbanas.","example":"Crescimento urbano sem saneamento adequado pode causar impactos ambientais e problemas de saúde.","sections":[{"heading":"Conceitos essenciais","text":"A população ocupa e transforma espaços."},{"heading":"Como compreender e aplicar","text":"Migração é deslocamento de pessoas entre lugares; urbanização envolve o crescimento e a concentração de atividades urbanas."}],"visual":{"icon":"🌎","steps":["①","②","③"],"labels":["MIGRAÇÃO","CIDADES","INFRAESTRUTURA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Crescimento urbano sem saneamento adequado pode causar impactos ambientais e problemas de saúde."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “população e espaço geográfico” a um colega que faltou à aula. Comece pela ideia: A população ocupa e transforma espaços. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: MIGRAÇÃO → CIDADES → INFRAESTRUTURA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."}],[{"title":"Vocabulário","summary":"Aprender vocabulário em inglês fica mais fácil quando relacionamos palavras a situações reais. Observe substantivos, verbos e expressões usadas em casa, na escola e na cidade.","example":"Book significa livro; school significa escola. Em 'Open your book', a instrução é abrir o livro.","sections":[{"heading":"Conceitos essenciais","text":"Aprender vocabulário em inglês fica mais fácil quando relacionamos palavras a situações reais."},{"heading":"Como compreender e aplicar","text":"Observe substantivos, verbos e expressões usadas em casa, na escola e na cidade."}],"visual":{"icon":"💬","steps":["①","②","③"],"labels":["PALAVRA","CONTEXTO","SENTIDO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Book significa livro; school significa escola. Em 'Open your book', a instrução é abrir o livro."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “vocabulário” a um colega que faltou à aula. Comece pela ideia: Aprender vocabulário em inglês fica mais fácil quando relacionamos palavras a situações reais. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PALAVRA → CONTEXTO → SENTIDO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Verbo to be","summary":"O verbo to be pode significar ser ou estar. No presente, usamos am com I, is com he/she/it e are com you/we/they.","example":"I am a student. She is happy. They are friends. Na pergunta, invertemos: 'Is she happy?'.","sections":[{"heading":"Conceitos essenciais","text":"O verbo to be pode significar ser ou estar."},{"heading":"Como compreender e aplicar","text":"No presente, usamos am com I, is com he/she/it e are com you/we/they."}],"visual":{"icon":"💬","steps":["①","②","③"],"labels":["I → AM","SHE → IS","THEY → ARE"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"I am a student. She is happy. They are friends. Na pergunta, invertemos: 'Is she happy?'."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “verbo to be” a um colega que faltou à aula. Comece pela ideia: O verbo to be pode significar ser ou estar. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: I → AM → SHE → IS → THEY → ARE. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Simple present","summary":"O simple present descreve hábitos, rotinas e fatos gerais. Com he, she e it, muitos verbos recebem -s ou -es. Em negativas e perguntas, usamos do/does.","example":"She plays soccer. Does she play soccer? They do not play on Mondays.","sections":[{"heading":"Conceitos essenciais","text":"O simple present descreve hábitos, rotinas e fatos gerais. Com he, she e it, muitos verbos recebem -s ou -es."},{"heading":"Como compreender e aplicar","text":"Em negativas e perguntas, usamos do/does."}],"visual":{"icon":"💬","steps":["①","②","③"],"labels":["I/WE → PLAY","SHE → PLAYS","DO/DOES"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"She plays soccer. Does she play soccer? They do not play on Mondays."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “simple present” a um colega que faltou à aula. Comece pela ideia: O simple present descreve hábitos, rotinas e fatos gerais. Com he, she e it, muitos verbos recebem -s ou -es. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: I/WE → PLAY → SHE → PLAYS → DO/DOES. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Cumprimentos e apresentações","summary":"Cumprimentos variam conforme o momento e a situação. Ao conhecer alguém, podemos perguntar o nome e responder com educação.","example":"Good morning = bom dia; Nice to meet you = prazer em conhecer você; My name is Ana = meu nome é Ana.","sections":[{"heading":"Conceitos essenciais","text":"Cumprimentos variam conforme o momento e a situação."},{"heading":"Como compreender e aplicar","text":"Ao conhecer alguém, podemos perguntar o nome e responder com educação."}],"visual":{"icon":"💬","steps":["①","②","③"],"labels":["HELLO","MY NAME IS...","NICE TO MEET YOU"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Good morning = bom dia; Nice to meet you = prazer em conhecer você; My name is Ana = meu nome é Ana."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “cumprimentos e apresentações” a um colega que faltou à aula. Comece pela ideia: Cumprimentos variam conforme o momento e a situação. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: HELLO → MY NAME IS... → NICE TO MEET YOU. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Família, escola e cotidiano","summary":"Palavras sobre família, escola e rotina ajudam a compreender pequenos textos. O contexto da frase indica quem pratica a ação e quando.","example":"Mother = mãe; brother = irmão; breakfast = café da manhã; 'I go to school' = eu vou à escola.","sections":[{"heading":"Conceitos essenciais","text":"Palavras sobre família, escola e rotina ajudam a compreender pequenos textos."},{"heading":"Como compreender e aplicar","text":"O contexto da frase indica quem pratica a ação e quando."}],"visual":{"icon":"💬","steps":["①","②","③"],"labels":["FAMILY","SCHOOL","ROUTINE"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Mother = mãe; brother = irmão; breakfast = café da manhã; 'I go to school' = eu vou à escola."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “família, escola e cotidiano” a um colega que faltou à aula. Comece pela ideia: Palavras sobre família, escola e rotina ajudam a compreender pequenos textos. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: FAMILY → SCHOOL → ROUTINE. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Pronomes e verbo to be","summary":"Pronomes pessoais substituem nomes: I, you, he, she, it, we, they. Cada grupo combina com uma forma do verbo to be.","example":"We are students; He is my brother; I am at home.","sections":[{"heading":"Conceitos essenciais","text":"Pronomes pessoais substituem nomes: I, you, he, she, it, we, they."},{"heading":"Como compreender e aplicar","text":"Cada grupo combina com uma forma do verbo to be."}],"visual":{"icon":"💬","steps":["①","②","③"],"labels":["I → AM","HE → IS","WE → ARE"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"We are students; He is my brother; I am at home."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “pronomes e verbo to be” a um colega que faltou à aula. Comece pela ideia: Pronomes pessoais substituem nomes: I, you, he, she, it, we, they. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: I → AM → HE → IS → WE → ARE. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Presente simples e perguntas","summary":"No presente simples, perguntas com verbos comuns geralmente usam do ou does. Com he/she/it, use does e o verbo principal sem -s.","example":"Does she like music? Yes, she does. Do they study? Yes, they do.","sections":[{"heading":"Conceitos essenciais","text":"No presente simples, perguntas com verbos comuns geralmente usam do ou does."},{"heading":"Como compreender e aplicar","text":"Com he/she/it, use does e o verbo principal sem -s."}],"visual":{"icon":"💬","steps":["①","②","③"],"labels":["DO YOU...?","DOES SHE...?","RESPOSTA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Does she like music? Yes, she does. Do they study? Yes, they do."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “presente simples e perguntas” a um colega que faltou à aula. Comece pela ideia: No presente simples, perguntas com verbos comuns geralmente usam do ou does. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: DO YOU...? → DOES SHE...? → RESPOSTA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Leitura e cultura em inglês","summary":"Ler em inglês exige observar palavras conhecidas, contexto e finalidade do texto. Placas, convites, bilhetes e horários ajudam a praticar compreensão.","example":"'The museum opens at nine' informa o horário de abertura do museu: nove horas.","sections":[{"heading":"Conceitos essenciais","text":"Ler em inglês exige observar palavras conhecidas, contexto e finalidade do texto."},{"heading":"Como compreender e aplicar","text":"Placas, convites, bilhetes e horários ajudam a praticar compreensão."}],"visual":{"icon":"💬","steps":["①","②","③"],"labels":["PLACA","INFORMAÇÃO","SENTIDO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"'The museum opens at nine' informa o horário de abertura do museu: nove horas."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “leitura e cultura em inglês” a um colega que faltou à aula. Comece pela ideia: Ler em inglês exige observar palavras conhecidas, contexto e finalidade do texto. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PLACA → INFORMAÇÃO → SENTIDO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Leitura e comunicação cotidiana","summary":"Comunicar-se em inglês envolve compreender perguntas frequentes, instruções e respostas adequadas. Não é necessário traduzir palavra por palavra para entender a mensagem.","example":"'How often do you read?' pergunta sobre frequência. Uma resposta possível é 'Every day'.","sections":[{"heading":"Conceitos essenciais","text":"Comunicar-se em inglês envolve compreender perguntas frequentes, instruções e respostas adequadas."},{"heading":"Como compreender e aplicar","text":"Não é necessário traduzir palavra por palavra para entender a mensagem."}],"visual":{"icon":"💬","steps":["①","②","③"],"labels":["PERGUNTA","CONTEXTO","RESPOSTA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"'How often do you read?' pergunta sobre frequência. Uma resposta possível é 'Every day'."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “leitura e comunicação cotidiana” a um colega que faltou à aula. Comece pela ideia: Comunicar-se em inglês envolve compreender perguntas frequentes, instruções e respostas adequadas. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PERGUNTA → CONTEXTO → RESPOSTA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Preposições e localização","summary":"Preposições indicam relações de lugar: in (dentro), on (sobre), under (embaixo), between (entre), behind (atrás) e next to (ao lado).","example":"'The cat is under the table' significa que o gato está embaixo da mesa.","sections":[{"heading":"Conceitos essenciais","text":"Preposições indicam relações de lugar: in (dentro), on (sobre), under (embaixo), between (entre), behind (atrás) e next to (ao lado)."},{"heading":"Como compreender e aplicar","text":"Observe a situação, identifique os dados importantes e relacione-os aos conceitos apresentados."}],"visual":{"icon":"💬","steps":["①","②","③"],"labels":["IN/ON","UNDER","BETWEEN"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"'The cat is under the table' significa que o gato está embaixo da mesa."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “preposições e localização” a um colega que faltou à aula. Comece pela ideia: Preposições indicam relações de lugar: in (dentro), on (sobre), under (embaixo), between (entre), behind (atrás) e next to (ao lado). Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: IN/ON → UNDER → BETWEEN. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."}],[{"title":"Artes visuais e música","summary":"As artes utilizam linguagens e elementos expressivos. Nas artes visuais, linha, forma, cor e textura criam sentidos; na música, ritmo, melodia, intensidade e timbre organizam sons.","example":"Linhas diagonais podem sugerir movimento; sons fortes e suaves criam contrastes musicais.","sections":[{"heading":"Conceitos essenciais","text":"As artes utilizam linguagens e elementos expressivos."},{"heading":"Como compreender e aplicar","text":"Nas artes visuais, linha, forma, cor e textura criam sentidos; na música, ritmo, melodia, intensidade e timbre organizam sons."}],"visual":{"icon":"🎨","steps":["①","②","③"],"labels":["LINHA/COR","RITMO/SOM","EXPRESSÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Linhas diagonais podem sugerir movimento; sons fortes e suaves criam contrastes musicais."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “artes visuais e música” a um colega que faltou à aula. Comece pela ideia: As artes utilizam linguagens e elementos expressivos. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: LINHA/COR → RITMO/SOM → EXPRESSÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Artes visuais","summary":"Desenho, pintura, escultura, fotografia e outras formas visuais expressam ideias. Artistas escolhem materiais, cores, enquadramentos e composições para criar efeitos.","example":"Uma pintura com cores frias pode transmitir uma sensação diferente de outra com cores quentes.","sections":[{"heading":"Conceitos essenciais","text":"Desenho, pintura, escultura, fotografia e outras formas visuais expressam ideias."},{"heading":"Como compreender e aplicar","text":"Artistas escolhem materiais, cores, enquadramentos e composições para criar efeitos."}],"visual":{"icon":"🎨","steps":["①","②","③"],"labels":["LINHA","FORMA","COR"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Uma pintura com cores frias pode transmitir uma sensação diferente de outra com cores quentes."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “artes visuais” a um colega que faltou à aula. Comece pela ideia: Desenho, pintura, escultura, fotografia e outras formas visuais expressam ideias. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: LINHA → FORMA → COR. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Música","summary":"Música combina sons e silêncios. Ritmo organiza durações; altura distingue graves e agudos; intensidade distingue fortes e suaves; timbre diferencia fontes sonoras.","example":"Um tambor e uma flauta podem tocar a mesma nota percebida com timbres diferentes.","sections":[{"heading":"Conceitos essenciais","text":"Música combina sons e silêncios."},{"heading":"Como compreender e aplicar","text":"Ritmo organiza durações; altura distingue graves e agudos; intensidade distingue fortes e suaves; timbre diferencia fontes sonoras."}],"visual":{"icon":"🎨","steps":["①","②","③"],"labels":["RITMO","ALTURA","TIMBRE"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Um tambor e uma flauta podem tocar a mesma nota percebida com timbres diferentes."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “música” a um colega que faltou à aula. Comece pela ideia: Música combina sons e silêncios. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: RITMO → ALTURA → TIMBRE. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Teatro e dança","summary":"Teatro reúne personagens, interpretação, cenário, figurino e expressão corporal. A dança utiliza corpo, espaço, tempo e ritmo para criar movimentos e sentidos.","example":"Uma personagem pode comunicar medo com gestos e expressão facial, mesmo sem falar.","sections":[{"heading":"Conceitos essenciais","text":"Teatro reúne personagens, interpretação, cenário, figurino e expressão corporal."},{"heading":"Como compreender e aplicar","text":"A dança utiliza corpo, espaço, tempo e ritmo para criar movimentos e sentidos."}],"visual":{"icon":"🎨","steps":["①","②","③"],"labels":["CORPO","ESPAÇO","CENA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Uma personagem pode comunicar medo com gestos e expressão facial, mesmo sem falar."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “teatro e dança” a um colega que faltou à aula. Comece pela ideia: Teatro reúne personagens, interpretação, cenário, figurino e expressão corporal. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: CORPO → ESPAÇO → CENA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Patrimônio e cultura","summary":"Patrimônio cultural inclui bens materiais, como edifícios e objetos, e imateriais, como saberes, festas e práticas transmitidas entre gerações.","example":"Uma construção histórica é bem material; uma tradição de dança pode ser patrimônio imaterial.","sections":[{"heading":"Conceitos essenciais","text":"Patrimônio cultural inclui bens materiais, como edifícios e objetos, e imateriais, como saberes, festas e práticas transmitidas entre gerações."},{"heading":"Como compreender e aplicar","text":"Observe a situação, identifique os dados importantes e relacione-os aos conceitos apresentados."}],"visual":{"icon":"🎨","steps":["①","②","③"],"labels":["BEM MATERIAL","SABER IMATERIAL","MEMÓRIA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Uma construção histórica é bem material; uma tradição de dança pode ser patrimônio imaterial."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “patrimônio e cultura” a um colega que faltou à aula. Comece pela ideia: Patrimônio cultural inclui bens materiais, como edifícios e objetos, e imateriais, como saberes, festas e práticas transmitidas entre gerações. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: BEM MATERIAL → SABER IMATERIAL → MEMÓRIA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Criação e interpretação","summary":"Criar arte envolve pesquisar, experimentar, esboçar, produzir e refletir sobre escolhas. Interpretar uma obra requer observar elementos e considerar contexto e diferentes pontos de vista.","example":"Antes de um mural, um esboço ajuda a organizar formas e cores.","sections":[{"heading":"Conceitos essenciais","text":"Criar arte envolve pesquisar, experimentar, esboçar, produzir e refletir sobre escolhas."},{"heading":"Como compreender e aplicar","text":"Interpretar uma obra requer observar elementos e considerar contexto e diferentes pontos de vista."}],"visual":{"icon":"🎨","steps":["①","②","③"],"labels":["IDEIA","ESBOÇO","CRIAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Antes de um mural, um esboço ajuda a organizar formas e cores."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “criação e interpretação” a um colega que faltou à aula. Comece pela ideia: Criar arte envolve pesquisar, experimentar, esboçar, produzir e refletir sobre escolhas. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: IDEIA → ESBOÇO → CRIAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Patrimônio cultural e manifestações","summary":"Manifestações culturais expressam memórias e identidades de grupos. Respeitar origens e praticantes é essencial para conhecer e valorizar a diversidade.","example":"Capoeira combina movimentos, música e saberes históricos compartilhados.","sections":[{"heading":"Conceitos essenciais","text":"Manifestações culturais expressam memórias e identidades de grupos."},{"heading":"Como compreender e aplicar","text":"Respeitar origens e praticantes é essencial para conhecer e valorizar a diversidade."}],"visual":{"icon":"🎨","steps":["①","②","③"],"labels":["TRADIÇÃO","COMUNIDADE","PRESERVAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Capoeira combina movimentos, música e saberes históricos compartilhados."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “patrimônio cultural e manifestações” a um colega que faltou à aula. Comece pela ideia: Manifestações culturais expressam memórias e identidades de grupos. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: TRADIÇÃO → COMUNIDADE → PRESERVAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."}],[{"title":"Jogos e esportes","summary":"Jogos e esportes envolvem regras, estratégias, cooperação e respeito. Vencer não justifica desrespeitar colegas ou alterar regras de forma injusta.","example":"No jogo coletivo, comunicação e ocupação de espaços ajudam a equipe.","sections":[{"heading":"Conceitos essenciais","text":"Jogos e esportes envolvem regras, estratégias, cooperação e respeito."},{"heading":"Como compreender e aplicar","text":"Vencer não justifica desrespeitar colegas ou alterar regras de forma injusta."}],"visual":{"icon":"🏃","steps":["①","②","③"],"labels":["REGRAS","ESTRATÉGIA","RESPEITO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"No jogo coletivo, comunicação e ocupação de espaços ajudam a equipe."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “jogos e esportes” a um colega que faltou à aula. Comece pela ideia: Jogos e esportes envolvem regras, estratégias, cooperação e respeito. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: REGRAS → ESTRATÉGIA → RESPEITO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Corpo e movimento","summary":"Movimentos exigem coordenação, equilíbrio, agilidade, força, resistência e flexibilidade em diferentes combinações. As capacidades podem ser desenvolvidas com prática adequada.","example":"Equilibrar-se em uma linha exige controle corporal; mudar rapidamente de direção exige agilidade.","sections":[{"heading":"Conceitos essenciais","text":"Movimentos exigem coordenação, equilíbrio, agilidade, força, resistência e flexibilidade em diferentes combinações."},{"heading":"Como compreender e aplicar","text":"As capacidades podem ser desenvolvidas com prática adequada."}],"visual":{"icon":"🏃","steps":["①","②","③"],"labels":["EQUILÍBRIO","AGILIDADE","COORDENAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Equilibrar-se em uma linha exige controle corporal; mudar rapidamente de direção exige agilidade."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “corpo e movimento” a um colega que faltou à aula. Comece pela ideia: Movimentos exigem coordenação, equilíbrio, agilidade, força, resistência e flexibilidade em diferentes combinações. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: EQUILÍBRIO → AGILIDADE → COORDENAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Jogos e brincadeiras","summary":"Brincadeiras são práticas culturais que podem mudar conforme o grupo e o lugar. Jogos cooperativos valorizam objetivos compartilhados e a participação de todos.","example":"Adaptar regras para incluir colegas pode tornar a brincadeira mais acessível e justa.","sections":[{"heading":"Conceitos essenciais","text":"Brincadeiras são práticas culturais que podem mudar conforme o grupo e o lugar."},{"heading":"Como compreender e aplicar","text":"Jogos cooperativos valorizam objetivos compartilhados e a participação de todos."}],"visual":{"icon":"🏃","steps":["①","②","③"],"labels":["PARTICIPAÇÃO","COOPERAÇÃO","INCLUSÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Adaptar regras para incluir colegas pode tornar a brincadeira mais acessível e justa."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “jogos e brincadeiras” a um colega que faltou à aula. Comece pela ideia: Brincadeiras são práticas culturais que podem mudar conforme o grupo e o lugar. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: PARTICIPAÇÃO → COOPERAÇÃO → INCLUSÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Esportes de marca e precisão","summary":"Nos esportes de marca, o resultado depende de tempo, distância ou altura. Nos de precisão, o objetivo é atingir um alvo com controle.","example":"Corrida e salto são exemplos de marca; boliche e tiro com arco são exemplos de precisão.","sections":[{"heading":"Conceitos essenciais","text":"Nos esportes de marca, o resultado depende de tempo, distância ou altura."},{"heading":"Como compreender e aplicar","text":"Nos de precisão, o objetivo é atingir um alvo com controle."}],"visual":{"icon":"🏃","steps":["①","②","③"],"labels":["TEMPO/DISTÂNCIA","ALVO","RESULTADO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Corrida e salto são exemplos de marca; boliche e tiro com arco são exemplos de precisão."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “esportes de marca e precisão” a um colega que faltou à aula. Comece pela ideia: Nos esportes de marca, o resultado depende de tempo, distância ou altura. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: TEMPO/DISTÂNCIA → ALVO → RESULTADO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Esportes de invasão e rede","summary":"Esportes de invasão envolvem avançar sobre um espaço defendido pelo adversário; esportes de rede dividem áreas por uma rede ou obstáculo semelhante.","example":"Handebol é esporte de invasão; voleibol é esporte de rede.","sections":[{"heading":"Conceitos essenciais","text":"Esportes de invasão envolvem avançar sobre um espaço defendido pelo adversário; esportes de rede dividem áreas por uma rede ou obstáculo semelhante."},{"heading":"Como compreender e aplicar","text":"Observe a situação, identifique os dados importantes e relacione-os aos conceitos apresentados."}],"visual":{"icon":"🏃","steps":["①","②","③"],"labels":["INVASÃO","REDE","COOPERAÇÃO"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Handebol é esporte de invasão; voleibol é esporte de rede."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “esportes de invasão e rede” a um colega que faltou à aula. Comece pela ideia: Esportes de invasão envolvem avançar sobre um espaço defendido pelo adversário; esportes de rede dividem áreas por uma rede ou obstáculo semelhante. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: INVASÃO → REDE → COOPERAÇÃO. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Ginásticas e saúde","summary":"Ginásticas podem desenvolver força, equilíbrio, coordenação e flexibilidade. Praticar com segurança inclui aquecimento, hidratação, descanso e respeito aos limites do corpo.","example":"Alongar-se gradualmente pode trabalhar a amplitude de movimento sem forçar até sentir dor.","sections":[{"heading":"Conceitos essenciais","text":"Ginásticas podem desenvolver força, equilíbrio, coordenação e flexibilidade."},{"heading":"Como compreender e aplicar","text":"Praticar com segurança inclui aquecimento, hidratação, descanso e respeito aos limites do corpo."}],"visual":{"icon":"🏃","steps":["①","②","③"],"labels":["AQUECER","MOVIMENTAR","DESCANSAR"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Alongar-se gradualmente pode trabalhar a amplitude de movimento sem forçar até sentir dor."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “ginásticas e saúde” a um colega que faltou à aula. Comece pela ideia: Ginásticas podem desenvolver força, equilíbrio, coordenação e flexibilidade. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: AQUECER → MOVIMENTAR → DESCANSAR. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Danças e aventuras","summary":"Dança combina movimentos, ritmo, espaço e expressão cultural. Práticas corporais de aventura exigem planejamento, cuidado com o ambiente e avaliação de riscos.","example":"Antes de uma trilha, confira percurso, clima, equipamentos e hidratação.","sections":[{"heading":"Conceitos essenciais","text":"Dança combina movimentos, ritmo, espaço e expressão cultural."},{"heading":"Como compreender e aplicar","text":"Práticas corporais de aventura exigem planejamento, cuidado com o ambiente e avaliação de riscos."}],"visual":{"icon":"🏃","steps":["①","②","③"],"labels":["RITMO","MOVIMENTO","SEGURANÇA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"Antes de uma trilha, confira percurso, clima, equipamentos e hidratação."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “danças e aventuras” a um colega que faltou à aula. Comece pela ideia: Dança combina movimentos, ritmo, espaço e expressão cultural. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: RITMO → MOVIMENTO → SEGURANÇA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Esportes de invasão e precisão","summary":"Esportes de invasão exigem estratégias coletivas para avançar e defender; esportes de precisão valorizam controle para atingir alvos.","example":"No futsal, passes e movimentação criam oportunidades; no boliche, direção e força do lançamento influenciam a precisão.","sections":[{"heading":"Conceitos essenciais","text":"Esportes de invasão exigem estratégias coletivas para avançar e defender; esportes de precisão valorizam controle para atingir alvos."},{"heading":"Como compreender e aplicar","text":"Observe a situação, identifique os dados importantes e relacione-os aos conceitos apresentados."}],"visual":{"icon":"🏃","steps":["①","②","③"],"labels":["ESPAÇO COLETIVO","PRECISÃO","ESTRATÉGIA"],"kind":"concept-map"},"examples":[{"title":"Exemplo explicado","text":"No futsal, passes e movimentação criam oportunidades; no boliche, direção e força do lançamento influenciam a precisão."},{"title":"Aplicação em outra situação","text":"Imagine que você precisa explicar “esportes de invasão e precisão” a um colega que faltou à aula. Comece pela ideia: Esportes de invasão exigem estratégias coletivas para avançar e defender; esportes de precisão valorizam controle para atingir alvos. Em seguida, crie uma situação diferente do exemplo anterior e explique como o conceito aparece nela."},{"title":"Verifique se compreendeu","text":"Sem consultar as perguntas do desafio, compare as três partes do esquema: ESPAÇO COLETIVO → PRECISÃO → ESTRATÉGIA. Qual é a relação entre elas? Explique com suas palavras e depois confira a explicação acima."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."}]];